      background: #2d2d2d;
      border-radius: 8px 8px 6px 6px;
      box-shadow: 0 16px 36px rgba(0, 0, 0, 0.55), 0 0 0 1px rgba(255, 255, 255, 0.1);
      display: flex;
      flex-direction: column;
      overflow: hidden;
      z-index: 100;
    }

    .window.hidden {
      display: none !important;
