    .win-maximize {
      background: #4a4a4a;
    }

    .win-body {
      flex: 1;
      display: flex;
      flex-direction: column;
      background: #1e1e1e;
      overflow: hidden;
    }

    /* Files App */
    .files-toolbar {
      height: 44px;
      background: #282828;
      display: flex;
      align-items: center;
      padding: 0 12px;
      gap: 12px;
      border-bottom: 1px solid #141414;
    }

    #files-up {
      background: #3c3c3c;
      color: #fff;
      border: 1px solid #505050;
      padding: 6px 14px;
      border-radius: 5px;
      cursor: pointer;
      font-size: 13px;
      font-weight: 500;
      display: flex;
      align-items: center;
      gap: 4px;
      transition: background 0.15s;
    }

    #files-up:hover {
      background: #4a4a4a;
    }

    #files-path {
      flex: 1;
      background: #181818;
      color: #e0e0e0;
      padding: 6px 12px;
      border-radius: 5px;
      font-family: monospace;
      font-size: 13px;
      border: 1px solid #333;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .files-grid {
      flex: 1;
      padding: 16px;
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(100px, 1fr));
      grid-auto-rows: max-content;
      gap: 14px;
      overflow-y: auto;
      background: #1e1e1e;
    }

    .fs-item {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 12px 8px;
      border-radius: 6px;
      cursor: pointer;
      color: #e0e0e0;
      font-size: 13px;
      text-align: center;
      word-break: break-word;
      transition: background 0.15s ease;
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid transparent;
    }

    .fs-item:hover {
      background: rgba(233, 84, 32, 0.22);
      border-color: rgba(233, 84, 32, 0.4);
    }

    .fs-item[data-type="dir"]::before {
      content: '📁';
      font-size: 32px;
      margin-bottom: 6px;
      display: block;
    }

    .fs-item[data-type="file"]::before {
      content: '📄';
      font-size: 32px;
      margin-bottom: 6px;
      display: block;
    }

    /* Notepad App */
    .notepad-toolbar {
      background: #252525;
      display: flex;
      align-items: center;
      padding: 4px 6px 0 6px;
      gap: 6px;
      border-bottom: 1px solid #141414;
    }

    #tabs {
      display: flex;
      align-items: center;
      gap: 4px;
      overflow-x: auto;
      flex: 1;
    }

    .tab {
      background: #171717;
      color: #a0a0a0;
      padding: 6px 12px;
      border-radius: 6px 6px 0 0;
      font-size: 13px;
      cursor: pointer;
      display: flex;
      align-items: center;
      gap: 8px;
      border: 1px solid transparent;
      border-bottom: none;
      max-width: 160px;
      white-space: nowrap;
      user-select: none;
    }

    .tab.active {
      background: #1e1e1e;
      color: #ffffff;
      border-color: #333;
      font-weight: 500;
    }

    .tab-close {
      font-size: 14px;
      line-height: 1;
      border-radius: 50%;
      width: 16px;
      height: 16px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: #888;
    }

    .tab-close:hover {
      background: rgba(255, 255, 255, 0.2);
      color: #fff;
    }

    #new-tab {
      background: transparent;
      border: none;
      color: #aaa;
      padding: 6px 10px;
      border-radius: 4px;
      cursor: pointer;
      font-size: 14px;
      font-weight: bold;
    }

    #new-tab:hover {
      background: rgba(255, 255, 255, 0.1);
      color: #fff;
    }

    #editor {
      flex: 1;
      background: #1e1e1e;
      color: #f0f0f0;
      border: none;
      outline: none;
      padding: 14px;
      font-family: "Ubuntu Mono", Consolas, Monaco, monospace;
      font-size: 14px;
      line-height: 1.5;
      resize: none;
    }
  </style>
</head>
<body>
  <div id="desktop">
    <!-- Top Panel -->
    <div id="top-bar">
      <div class="top-bar-left">
        <span class="top-bar-item">Activities</span>
      </div>
      <div class="top-bar-center">
        <span id="clock" class="top-bar-item">Oct 24 12:00</span>
      </div>
      <div class="top-bar-right">
        <span class="top-bar-item">📶</span>
        <span class="top-bar-item">🔊</span>
        <span class="top-bar-item">⏻</span>
      </div>
    </div>

    <!-- Dock / Taskbar -->
    <div id="taskbar">
      <button id="open-files" class="dock-btn" title="Files">📁</button>
      <button id="open-notepad" class="dock-btn" title="Notepad">📝</button>
    </div>

    <!-- Files Window -->
    <div id="files-window" class="window hidden" style="left: 120px; top: 60px;">
      <div class="win-header">
        <div class="win-title">
          <span>📁</span> Files
        </div>
        <div class="win-controls">
          <button class="win-btn win-minimize">−</button>
          <button class="win-btn win-maximize">□</button>
          <button class="win-btn win-close" title="Close">×</button>
        </div>
      </div>
      <div class="win-body">
        <div class="files-toolbar">
          <button id="files-up">⬆ Up</button>
          <div id="files-path">/</div>
        </div>
        <div id="files-list" class="files-grid"></div>
      </div>
    </div>

    <!-- Notepad Window -->
    <div id="notepad-window" class="window hidden" style="left: 180px; top: 100px;">
      <div class="win-header">
        <div class="win-title">
          <span>📝</span> Text Editor
        </div>
        <div class="win-controls">
          <button class="win-btn win-minimize">−</button>
          <button class="win-btn win-maximize">□</button>
          <button class="win-btn win-close" title="Close">×</button>
        </div>
      </div>
      <div class="win-body">
        <div class="notepad-toolbar">
          <div id="tabs"></div>
          <button id="new-tab" title="New Tab">+</button>
        </div>
        <textarea id="editor" placeholder="Type your notes here..."></textarea>
      </div>
    </div>
  </div>

  <script>
    // --- Clock ---
    function updateClock() {
      const clock = document.getElementById('clock');
      if (!clock) return;
      const now = new Date();
      const opts = { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false };
      clock.textContent = now.toLocaleDateString('en-US', opts).replace(',', '');
    }
    setInterval(updateClock, 1000);
    updateClock();

    // --- Window Dragging & Z-Index ---
    let highestZ = 100;
    function bringToFront(win) {
      highestZ++;
      win.style.zIndex = highestZ;
    }

    function setupDragging(winId) {
      const win = document.getElementById(winId);
      if (!win) return;
      const header = win.querySelector('.win-header');

      let isDragging = false;
      let startX, startY, initLeft, initTop;

      header.addEventListener('mousedown', (e) => {
        if (e.target.closest('.win-controls')) return;
        isDragging = true;
        bringToFront(win);
        startX = e.clientX;
        startY = e.clientY;
        initLeft = win.offsetLeft;
        initTop = win.offsetTop;

        const onMouseMove = (ev) => {
          if (!isDragging) return;
          const dx = ev.clientX - startX;
          const dy = ev.clientY - startY;
          win.style.left = Math.max(0, initLeft + dx) + 'px';
          win.style.top = Math.max(28, initTop + dy) + 'px';
        };

        const onMouseUp = () => {
          isDragging = false;
          document.removeEventListener('mousemove', onMouseMove);
          document.removeEventListener('mouseup', onMouseUp);
        };

        document.addEventListener('mousemove', onMouseMove);
        document.addEventListener('mouseup', onMouseUp);
      });

      win.addEventListener('mousedown', () => bringToFront(win));
    }

    setupDragging('files-window');
    setupDragging('notepad-window');

    // Close buttons handler
    document.querySelectorAll('.win-close').forEach(btn => {
      btn.addEventListener('click', () => {
        const win = btn.closest('.window');
        if (win) {
          win.classList.add('hidden');
        }
      });
    });

    // Launchers
    document.getElementById('open-files').addEventListener('click', () => {
      const win = document.getElementById('files-window');
      win.classList.remove('hidden');
      bringToFront(win);
    });

    document.getElementById('open-notepad').addEventListener('click', () => {
      const win = document.getElementById('notepad-window');
      win.classList.remove('hidden');
      bringToFront(win);
    });

    // --- Filesystem replica ---
    let currentPath = '/';

    const fsTree = {
      'bin': { type: 'dir', children: { 'sh': { type: 'file' }, 'bash': { type: 'file' } } },
      'etc': { type: 'dir', children: { 'hostname': { type: 'file' }, 'os-release': { type: 'file' } } },
      'home': {
        type: 'dir',
        children: {
          'user': {
            type: 'dir',
            children: {
              'Documents': { type: 'dir', children: { 'notes.txt': { type: 'file' }, 'project.md': { type: 'file' } } },
              'Downloads': { type: 'dir', children: { 'ubuntu-24.04.iso': { type: 'file' } } },
              'Pictures': { type: 'dir', children: { 'wallpaper.png': { type: 'file' }, 'avatar.png': { type: 'file' } } },
              'readme.txt': { type: 'file' }
            }
          }
        }
      },
      'usr': { type: 'dir', children: { 'bin': { type: 'dir', children: {} }, 'local': { type: 'dir', children: {} } } },
      'var': { type: 'dir', children: { 'log': { type: 'dir', children: {} }, 'tmp': { type: 'dir', children: {} } } }
    };

    function getNodeAtPath(pathStr) {
      if (pathStr === '/') return { type: 'dir', children: fsTree };
      const parts = pathStr.split('/').filter(Boolean);
      let curr = { children: fsTree };
      for (const part of parts) {
        if (curr && curr.children && curr.children[part]) {
          curr = curr.children[part];
        } else {
          return null;
        }
      }
      return curr;
    }

    function renderFiles() {
      const pathEl = document.getElementById('files-path');
      const container = document.getElementById('files-list');
      if (pathEl) pathEl.textContent = currentPath;
      if (!container) return;

      container.innerHTML = '';
      const node = getNodeAtPath(currentPath);
      if (!node || !node.children) return;

      const entries = Object.keys(node.children).sort((a, b) => {
        const itemA = node.children[a];
        const itemB = node.children[b];
        if (itemA.type !== itemB.type) {
          return itemA.type === 'dir' ? -1 : 1;
        }
        return a.localeCompare(b);
      });

      entries.forEach(name => {
        const item = node.children[name];
        const el = document.createElement('div');
        el.className = 'fs-item';
        el.dataset.type = item.type;
        el.dataset.name = name;
        el.textContent = name;

        el.addEventListener('dblclick', (e) => {
          e.preventDefault();
          if (item.type === 'dir') {
            currentPath = currentPath === '/' ? '/' + name : currentPath + '/' + name;
            renderFiles();
          }
        });

        container.appendChild(el);
      });
    }

    document.getElementById('files-up').addEventListener('click', () => {
      if (currentPath === '/') return;
      const lastSlash = currentPath.lastIndexOf('/');
      if (lastSlash <= 0) {
        currentPath = '/';
      } else {
        currentPath = currentPath.substring(0, lastSlash);
      }
      renderFiles();
    });

    renderFiles();

    // --- Notepad App with LocalStorage Persistence ---
    const NOTEPAD_KEY = 'ubuntu_notepad_state';

    let notepadState = {
      activeIndex: 0,
      tabs: [
        { title: 'Document 1', content: 'Welcome to Ubuntu Notepad!\nYour changes are saved automatically.' }
      ]
    };

    function loadNotepad() {
      try {
        const saved = localStorage.getItem(NOTEPAD_KEY);
        if (saved) {
          const parsed = JSON.parse(saved);
          if (parsed && Array.isArray(parsed.tabs) && parsed.tabs.length > 0) {
            notepadState = parsed;
            if (notepadState.activeIndex < 0 || notepadState.activeIndex >= notepadState.tabs.length) {
              notepadState.activeIndex = 0;
            }
          }
        }
      } catch (e) {
        console.error('Failed to load notepad state:', e);
      }
    }

    function saveNotepad() {
      try {
        localStorage.setItem(NOTEPAD_KEY, JSON.stringify(notepadState));
      } catch (e) {
        console.error('Failed to save notepad state:', e);
      }
    }

    function renderNotepad() {
      const tabsContainer = document.getElementById('tabs');
      const editor = document.getElementById('editor');
      if (!tabsContainer || !editor) return;

      tabsContainer.innerHTML = '';

      notepadState.tabs.forEach((tab, index) => {
        const tabEl = document.createElement('div');
        tabEl.className = 'tab' + (index === notepadState.activeIndex ? ' active' : '');

        const titleSpan = document.createElement('span');
        titleSpan.textContent = tab.title || 'Untitled';
        tabEl.appendChild(titleSpan);

        if (notepadState.tabs.length > 1) {
          const closeBtn = document.createElement('span');
          closeBtn.className = 'tab-close';
          closeBtn.innerHTML = '&times;';
          closeBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            closeTab(index);
          });
          tabEl.appendChild(closeBtn);
        }

        tabEl.addEventListener('click', () => {
          switchTab(index);
        });

        tabsContainer.appendChild(tabEl);
      });

      if (notepadState.tabs[notepadState.activeIndex]) {
        editor.value = notepadState.tabs[notepadState.activeIndex].content;
      } else {
        editor.value = '';
      }
    }

    function switchTab(index) {
      if (index >= 0 && index < notepadState.tabs.length) {
        notepadState.activeIndex = index;
        saveNotepad();
        renderNotepad();
      }
    }

    function closeTab(index) {
      if (notepadState.tabs.length <= 1) return;
      notepadState.tabs.splice(index, 1);
      if (notepadState.activeIndex >= notepadState.tabs.length) {
        notepadState.activeIndex = notepadState.tabs.length - 1;
      }
      saveNotepad();
      renderNotepad();
    }

    document.getElementById('new-tab').addEventListener('click', () => {
      const newNum = notepadState.tabs.length + 1;
      notepadState.tabs.push({
        title: `Untitled ${newNum}`,
        content: ''
      });
      notepadState.activeIndex = notepadState.tabs.length - 1;
      saveNotepad();
      renderNotepad();
    });

    document.getElementById('editor').addEventListener('input', (e) => {
      if (notepadState.tabs[notepadState.activeIndex]) {
        notepadState.tabs[notepadState.activeIndex].content = e.target.value;
        saveNotepad();
      }
    });

    // Initialize Notepad
    loadNotepad();
    renderNotepad();
  </script>
</body>
</html>
